BEGIN;
SELECT plan(19);
CREATE TEMP TABLE tap_runs(msg text);
CREATE TEMP TABLE op_vars(name text,id uuid,payload jsonb);
GRANT ALL ON tap_runs,op_vars TO authenticated;
WITH a AS(INSERT INTO public.accounts(workspace_id,name,type,initial_balance,current_balance) SELECT id,'Receipt bank','cash',1000,1000 FROM op_vars WHERE name='ws' RETURNING id) INSERT INTO op_vars SELECT 'account',id,NULL FROM a;
SET LOCAL request.jwt.claim.sub='a3500000-0000-0000-0000-000000000001';
SET LOCAL role='authenticated';
UPDATE op_vars SET id=public.fn_execute_financial_operation((SELECT id FROM op_vars WHERE name='ws'),'fn_record_payment','payment-1',payload) WHERE name='pay';
SELECT public.fn_execute_financial_operation((SELECT id FROM op_vars WHERE name='ws'),'fn_record_payment','payment-2',(SELECT payload FROM op_vars WHERE name='pay'));
UPDATE op_vars SET id=public.fn_execute_financial_operation((SELECT id FROM op_vars WHERE name='ws'),'fn_create_purchase_with_splits','purchase-1',payload) WHERE name='purchase';
SELECT public.fn_delete_transaction((SELECT id FROM op_vars WHERE name='ws'),(SELECT id FROM op_vars WHERE name='tx'));
RESET ROLE;
SELECT (SELECT array_agg(msg) FROM tap_runs WHERE msg LIKE 'not ok%') AS not_ok_messages,
 extensions._get('curr_test')::int AS ran,extensions._get('plan')::int AS planned,extensions.num_failed()::int AS failed,ARRAY(SELECT * FROM extensions.finish()) AS finish_diagnostics;
ROLLBACK;
